// Yellow paint: a painted ring on the ground marks anything you can use (trampolines, supply tables, cheese wheels).
fn paint65(c:vec2f,r:f32){for(var k=0u;k<16u;k++){let a=f32(k)*.3927;let q=c+vec2f(cos(a),sin(a))*r;box(vec3f(q.x,.012,q.y),vec3f(.34,.02,.34),vec3f(1,.84,.12),1,.35);}}
